resources.string:
GuidePosition.Custom { anchorRect, tooltipSize, available ->
	val left = available.centerX() - tooltipSize.width / 2
	val top = available.bottom - tooltipSize.height - marginPx
	Rect(
		left, top,
		left + tooltipSize.width,
		top + tooltipSize.height
	)
}

// 快捷写法
GuidePosition.custom { anchorRect, tooltipSize, available -> ... }

GuidePosition.Relative(side = Side.BOTTOM)
overflow = Overflow.FLIP_THEN_CLAMP

// FLIP 只翻边
// CLAMP 只平移
// NONE 不约束（调试）

// 1. 内置内容
GuideContent.Default(
	title = "标题",
	message = "正文",
	primaryLabel = "下一步",
	finishLabel = "完成",
	skipLabel = null
)

// 2. 原始布局 + findViewById
GuideContent.Custom(R.layout.my_guide) { view, session ->
	view.findViewById<View>(R.id.next)
		.setOnClickListener { session.next() }
}

// 3. ViewBinding
GuideContent.CustomBinding(
	create = { inflater, parent ->
		MyGuideBinding.inflate(inflater, parent, false)
	},
	bind = { binding, session ->
		binding.next.setOnClickListener { session.next() }
	}
)

GuideContent.CustomBinding(
	create = { inflater, parent ->
		SessionBinding.inflate(inflater, parent, false)
	},
	bind = { binding, session ->
		binding.previous.setOnClickListener { session.previous() }
		binding.next.setOnClickListener { session.next() }
		binding.goTo.setOnClickListener { session.goTo(2) }
		binding.finish.setOnClickListener { session.finish() }
		binding.skip.setOnClickListener { session.skip() }
		binding.dismiss.setOnClickListener { session.dismiss() }
	}
)

GuideHighlight(
	holeAnimation = HoleAnimation.Scale(
		duration = 420L,
		startScale = 0.2f,
		fadeScrim = true
	),
	animate = true
)

// None / Scale / Fade

GuideAnchor.RecyclerViewItemAnchor(
	recyclerView = recycler,
	position = 7,
	childId = R.id.itemAction,
	scrollToItem = true
)

// 已可见时
scrollToItem = false
// 整个 item
childId = View.NO_ID

GuideListener:
 onStepShown(index, step)
 onStepLocated(index, anchorRect, holeRect, tooltipRect)
 onGuideEnded(reason)

// GuideEndReason
// FINISHED / SKIPPED / DISMISSED
// ANCHOR_LOST / HOST_DESTROYED

GuideContent.Custom(R.layout.my_guide) { view, session ->
 view.findViewById<View>(R.id.next)
 .setOnClickListener { session.next() }
}

GuideContent.CustomBinding(
 create = { inflater, parent ->
 MyGuideBinding.inflate(inflater, parent, false)
 },
 bind = { binding, session ->
 binding.next.setOnClickListener { session.next() }
 }
)

GuideTooltip(
 animation = BubbleAnimation.Fade(400L)
)

// None / Fade / Scale / Slide
BubbleAnimation.Scale(
 duration = 420L,
 startScale = 0.85f
)
BubbleAnimation.Slide(
 duration = 420L,
 offset = 16.dp
)

GuideAnchor.RecyclerViewItemAnchor(
 recyclerView = recycler,
 position = 7,
 childId = R.id.itemAction,
 scrollToItem = true
)

// 等待期间 isPending() 为 true
// 不会触发 anchorLostPolicy
